import {levels,questions,summarize} from './content.js';
import {art} from './art.js';
import {roster,dateTime,exportRows,exportDetails} from './teacher-data.js';
const API='https://eoweuhjuazcjjztnugoi.supabase.co/functions/v1/inheritance-api';
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let student=null,events=[],teacherToken=sessionStorage.getItem('trait-teacher')||'',teacherData=null,rows=[],level=0,index=0,selected=null,feedback=null,busy=false,filterClass='',filterState='',pending=null;
try{student=JSON.parse(sessionStorage.getItem('trait-student')||'null');if(student)events=student.events||[];}catch{}
async function api(action,body={},token=student?.token){
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),16000);
 try{const res=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json',...(token?{'Authorization':'Bearer '+token}:{})},body:JSON.stringify({action,...body}),signal:controller.signal});const json=await res.json();if(!res.ok){const error=new Error(json.error||'連線未成功，請重試。');error.status=res.status;throw error;}return json;}finally{clearTimeout(timeout);}
}
function persist(){if(student){student.events=events;sessionStorage.setItem('trait-student',JSON.stringify(student));}}
function toast(t){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),4000);}
function focusMain(){app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function home(){
 feedback=null;selected=null;const s=summarize(events);
 app.innerHTML=`<section class="hero"><div><span class="tag">小四科學 · 生命的延續</span><h1>相似的小秘密，<br>等你來發現。</h1><p class="intro">一片葉子、一朵小花、一張熟悉的臉……<br>親代和子代，有哪些相似的特徵？<br>帶上你的好奇心，成為特徵小偵探！</p><span class="eyebrow">觀察線索 → 比較特徵 → 找出子代</span></div><div class="hero-art" aria-label="葉子、花朵和小貓的探索插圖"><div class="art-main">${art({type:'collection'})}</div><div class="art-card one">${art({type:'leaf',shape:'oval'})}葉形的線索</div><div class="art-card two">${art({type:'cat',color:'#d79d59'})}生命的相似</div><span class="art-note">每個生命，都有小秘密</span><span class="dot-stamp">一起<br>找子代</span></div></section>
 ${student?`<section class="student-bar"><div><strong>${student.class} 班 · ${student.student_no} 號</strong><div class="small">已完成 ${s.levels.filter(Boolean).length} / 6 關 · 已答對 ${s.solved.length} / 18 題</div></div><div class="button-row"><button class="primary" id="continue">${s.levels.every(Boolean)?'查看探險成果':'繼續探索 →'}</button><button class="nav-btn" id="switch">更換學生</button></div></section>`:`<form class="login-strip" id="student-form"><h3>準備好出發了嗎？</h3><div class="field"><label for="class">你的班別</label><select id="class" required><option value="">請選擇班別</option>${['4A','4B','4C'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="number">你的學號</label><select id="number" required><option value="">請選擇學號</option>${Array.from({length:25},(_,i)=>`<option value="${i+1}">${i+1} 號</option>`).join('')}</select></div><button class="primary" type="submit">開始探索 →</button></form>`}
 <p class="login-note">${student?'完成紀錄已接通雲端。作答後看到「已儲存」才可離開。':'請選自己的班別和學號。網站只記錄班別、學號及作答情況，不收集姓名、照片或真實家庭特徵。'}</p>
 <div class="section-title"><h2>你的六站探索旅程</h2><span class="muted small">每關 3 題 · 按次序解鎖<br>答錯也可再觀察、再嘗試</span></div><div class="level-grid">${levels.map((l,i)=>{const unlocked=!student||i===0||s.levels[i-1],done=s.levels[i];return `<button class="level-card" data-level="${i}" ${!unlocked?'disabled':''}><span class="level-no">0${i+1}</span><span class="icon" style="background:${l.color}">${l.icon}</span><h3>${l.name}</h3><p>${l.goal}</p><div class="status"><span class="${done?'completed':''}">${done?'✓ 已完成':unlocked?'等待探索':'🔒 完成上一關後解鎖'}</span><span>${done?'再看看 ↗':'前往 →'}</span></div></button>`;}).join('')}</div><p class="book-note">遊戲以虛構的觀察紀錄配對。相似外貌不能用來確定現實中的親子關係。</p>`;
 $('#student-form')?.addEventListener('submit',start);
 $('#continue')?.addEventListener('click',()=>{if(s.levels.every(Boolean))finish();else openLevel(s.levels.findIndex(x=>!x));});
 $('#switch')?.addEventListener('click',()=>{student=null;events=[];pending=null;sessionStorage.removeItem('trait-student');home();focusMain();});
 document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{if(!student){$('#class').focus();toast('先選班別和學號，就能開始！');}else openLevel(Number(b.dataset.level));});
}
async function start(e){e.preventDefault();const b=e.submitter;b.disabled=true;b.textContent='正在連接…';try{student=await api('start',{class:$('#class').value,student_no:Number($('#number').value)},'');events=[];persist();home();openLevel(0);}catch(err){toast(err.message);b.disabled=false;b.textContent='開始探索 →';}}
function openLevel(n){if(busy)return;level=n;const qs=questions.filter(q=>q.level===level),done=new Set(summarize(events).solved);index=qs.findIndex(q=>!done.has(q.id));if(index<0)index=0;selected=null;feedback=null;pending=null;game();focusMain();}
function game(){
 const l=levels[level],qs=questions.filter(q=>q.level===level),q=qs[index],s=summarize(events),solved=s.solved.includes(q.id);
 if(solved&&!feedback)feedback={correct:true,why:q.why,saved:true};
 app.innerHTML=`<div class="game-top"><button class="back" id="back">← 探索地圖</button><span>${student.class} · ${student.student_no} 號 <span class="muted">｜第 ${level+1} 關，共 6 關</span></span></div><span class="eyebrow">${l.icon} ${l.name} · 第 ${index+1} / 3 題</span><div class="progress"><i style="width:${s.solved.length/18*100}%"></i></div><div class="game-layout"><aside class="parent-card"><span class="tag">先觀察親代</span>${art(q.parent)}<strong>${q.parentLabel}</strong></aside><section class="question-area"><h2>${q.title}</h2><p class="clue">🔎 ${q.clue}</p><div class="options">${q.options.map((o,i)=>`<button class="option ${selected===i?'selected':''} ${selected===i&&feedback?(feedback.correct?'correct':'wrong'):''}" data-choice="${i}" aria-pressed="${selected===i}" ${solved||busy?'disabled':''}>${art(o.art)}<span>${o.label}</span></button>`).join('')}</div>${feedback?`<div class="feedback ${feedback.correct?'':'notice'}" role="status"><strong>${feedback.error?'暫未儲存':feedback.correct?'✓ 觀察得很好！':'再觀察一次，你做得到！'}</strong><p>${esc(feedback.why)}</p><div class="button-row">${feedback.correct?`<button class="primary" id="next">${index===2?'完成這一關 →':'下一題 →'}</button><span class="small">☁ 已儲存</span>`:feedback.error?'<button class="primary" id="retry-save">重試儲存</button>':'<button class="secondary" id="retry">再試一次</button><span class="small">本次嘗試已儲存</span>'}</div></div>`:''}<div class="question-actions"><span class="muted small">先點選答案，再確認。</span>${!solved&&!feedback?`<button class="primary" id="confirm" ${selected===null||busy?'disabled':''}>${busy?'正在儲存…':'確認答案 ✓'}</button>`:''}</div><p class="book-note">親代：上一代　｜　子代：後代<br>${level===3||level===4||level===5?'人物皆為虛構。請根據提供的觀察紀錄配對。':'這是特徵比較活動，請配合提供的觀察紀錄。'}</p></section></div>`;
 $('#back').onclick=()=>{if(!busy){home();focusMain();}};
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.choice);feedback=null;pending=null;game();});
 $('#confirm')?.addEventListener('click',submitAnswer);$('#retry-save')?.addEventListener('click',submitAnswer);
 $('#retry')?.addEventListener('click',()=>{selected=null;feedback=null;pending=null;game();});
 $('#next')?.addEventListener('click',()=>{if(index<2){index++;selected=null;feedback=null;pending=null;game();focusMain();}else completeLevel();});
}
async function submitAnswer(){
 if(busy||selected===null)return;busy=true;feedback=null;
 const q=questions.filter(q=>q.level===level)[index];pending??={question_id:q.id,choice:selected,event_id:crypto.randomUUID()};game();
 try{const res=await api('answer',pending);events=res.events;persist();feedback={correct:res.correct,why:res.correct?res.why:'留意紀錄中要比較的特徵，再仔細看看三個選項。'};pending=null;}catch(err){feedback={correct:false,error:true,why:err.message+' 請按「重試儲存」，不要關閉此頁。'};}finally{busy=false;game();}
}
function completeLevel(){const s=summarize(events);app.innerHTML=`<section class="celebrate"><div class="badge">${levels[level].icon}</div><span class="eyebrow">探索印章 +1</span><h1 style="font-size:42px">${levels[level].name}，完成！</h1><p class="muted">你已完成 ${s.levels.filter(Boolean).length} / 6 關。每一次比較，都是新的發現。</p><p>${levels[level].goal}</p><div class="button-row" style="justify-content:center"><button class="primary" id="advance">${level===5?'查看探險成果 →':'前往下一關 →'}</button><button class="secondary" id="map">返回地圖</button></div></section>`;$('#advance').onclick=()=>level===5?finish():openLevel(level+1);$('#map').onclick=home;focusMain();}
function finish(){const s=summarize(events);app.innerHTML=`<section class="celebrate"><div class="badge">🏅</div><span class="eyebrow">TRAIT DETECTIVE · MISSION COMPLETE</span><h1 style="font-size:42px">恭喜你，特徵小偵探！</h1><p>${student.class} 班 · ${student.student_no} 號</p><div class="stats"><div class="stat"><b>${s.levels.filter(Boolean).length}/6</b><span>已完成關卡</span></div><div class="stat"><b>${s.solved.length}/18</b><span>已答對題數</span></div><div class="stat"><b>${s.firstCorrect}/18</b><span>首次答對題數</span></div></div><p>子代具有與親代相似的特徵。<br>眼睛顏色、耳垂形狀等特徵可從親代繼承；<br>頭髮長度則不是遺傳特徵。</p><p class="small muted">☁ 完成紀錄已儲存，老師可在教師平台查看。<br>答錯後再嘗試，也是學習的一部分。</p><div class="button-row" style="justify-content:center"><button class="primary" id="map">回到探索地圖</button><button class="secondary" id="restart">重新挑戰一輪</button></div><p class="small muted">重新挑戰會保留歷次紀錄，教師表格以最新一輪顯示進度。</p></section>`;$('#map').onclick=home;$('#restart').onclick=async()=>{const b=$('#restart');b.disabled=true;try{student=await api('start',{class:student.class,student_no:student.student_no},'');events=[];persist();openLevel(0);}catch(e){toast(e.message);b.disabled=false;}};focusMain();}
function teacherLogin(message=''){
 app.innerHTML=`<section class="teacher-login"><span class="eyebrow">TEACHER SPACE</span><h2>教師觀察紀錄室</h2><p class="muted small">查看 4A–4C 共 75 位學生的探索進度。</p><form id="teacher-form"><div class="field"><label for="password">教師密碼</label><input type="password" id="password" required autocomplete="current-password"></div>${message?`<p class="notice error" role="alert">${esc(message)}</p>`:''}<button class="primary">登入教師平台 →</button></form><p class="book-note">僅記錄班別、學號和作答資料。登入於四小時後失效。</p></section>`;
 $('#teacher-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;b.textContent='登入中…';try{const r=await api('teacher-login',{password:$('#password').value},'');teacherToken=r.token;sessionStorage.setItem('trait-teacher',teacherToken);await loadTeacher();}catch(err){teacherLogin(err.message);}};
}
async function loadTeacher(){app.innerHTML='<p class="empty" role="status">正在讀取雲端紀錄…</p>';try{teacherData=await api('teacher-data',{},teacherToken);rows=roster(teacherData);dashboard();}catch(err){if(err.status===401){teacherToken='';sessionStorage.removeItem('trait-teacher');teacherLogin(err.message);}else{app.innerHTML=`<p class="notice error">${esc(err.message)}</p><button class="primary" id="reload-teacher">重新讀取</button>`;$('#reload-teacher').onclick=loadTeacher;}}}
function filtered(){return rows.filter(r=>(!filterClass||r.class===filterClass)&&(!filterState||(filterState==='done'?r.completed:filterState==='new'?!r.started:r.started&&!r.completed)));}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function dashboard(){
 const list=filtered();
 app.innerHTML=`<div class="section-title"><div><span class="eyebrow">TEACHER SPACE · LIVE RECORDS</span><h2>每一步探索，都看得見。</h2></div><button class="secondary" id="logout">登出</button></div><div class="stats"><div class="stat"><b>${rows.length}</b><span>全級學生</span></div><div class="stat"><b>${rows.filter(r=>r.started).length}</b><span>已開始學生</span></div><div class="stat"><b>${rows.filter(r=>r.completed).length}</b><span>六關全部完成</span></div></div><div class="toolbar"><div class="field"><label for="filter-class">班別</label><select id="filter-class"><option value="">全部班別</option>${['4A','4B','4C'].map(x=>`<option ${filterClass===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="filter-state">完成情況</label><select id="filter-state"><option value="">全部狀態</option><option value="new" ${filterState==='new'?'selected':''}>未開始</option><option value="active" ${filterState==='active'?'selected':''}>進行中</option><option value="done" ${filterState==='done'?'selected':''}>全部完成</option></select></div><button class="primary" id="export">匯出進度 CSV ↓</button><button class="secondary" id="export-detail">匯出作答明細 ↓</button><button class="secondary" id="refresh">重新整理 ↻</button></div><p class="small muted">下表顯示最新一輪的進度；明細保留歷次作答。首次答對題數不會因重試而增加。<br>顯示 ${list.length} 位學生 · 最後更新：${dateTime(teacherData.at)}（香港時間）</p><div class="table-wrap"><table><thead><tr><th>班別</th><th>學號</th><th>狀態</th><th>完成關卡</th><th>已答對</th><th>首次答對</th>${levels.map((l,i)=>`<th>${i+1}. ${l.name}</th>`).join('')}<th>最後活動</th><th>明細</th></tr></thead><tbody>${list.map(r=>`<tr><td>${r.class}</td><td>${r.no}</td><td><span class="pill ${r.completed?'completed':''}">${!r.started?'未開始':r.completed?'全部完成':'進行中'}</span></td><td>${r.summary.levels.filter(Boolean).length} / 6</td><td>${r.summary.solved.length} / 18</td><td>${r.summary.firstCorrect} / 18</td>${r.summary.levels.map((v,i)=>`<td>${v?'✓ 完成':r.latest&&questions.some(q=>q.level===i&&r.summary.solved.includes(q.id))?'進行中':'—'}</td>`).join('')}<td>${dateTime(r.at)}</td><td><button data-student="${r.class}-${r.no}">查看</button></td></tr>`).join('')||'<tr><td colspan="14" class="empty">沒有符合條件的學生。</td></tr>'}</tbody></table></div><div id="details"></div><p class="book-note">學生使用班別及學號自行選擇身份，適合課堂進度觀察。此登入方式不驗證學生本人。<br>CSV 依目前篩選匯出；進度檔包含未開始學生，作答明細包含各輪每次嘗試。</p>`;
 $('#filter-class').onchange=e=>{filterClass=e.target.value;dashboard();};$('#filter-state').onchange=e=>{filterState=e.target.value;dashboard();};
 $('#refresh').onclick=loadTeacher;$('#export').onclick=()=>download(exportRows(filtered()),'特徵小偵探_學生進度.csv');$('#export-detail').onclick=()=>download(exportDetails(filtered()),'特徵小偵探_作答明細.csv');
 $('#logout').onclick=async()=>{try{await api('teacher-logout',{},teacherToken);}catch{}teacherToken='';teacherData=null;rows=[];sessionStorage.removeItem('trait-teacher');teacherLogin();};
 document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>detail(rows.find(r=>r.class+'-'+r.no===b.dataset.student)));
}
function detail(r){
 $('#details').innerHTML=`<section class="detail"><h3>${r.class} 班 · ${r.no} 號｜作答紀錄</h3>${!r.started?'<p class="muted">這位學生尚未開始。</p>':`<p class="small">進入 ${r.sessions.length} 次 · 歷次最佳首次答對 ${r.best} / 18</p>${r.sessions.map((s,i)=>`<details ${i===r.sessions.length-1?'open':''}><summary>第 ${i+1} 輪 · ${dateTime(s.created_at)} · 首次答對 ${summarize(s.events).firstCorrect}/18</summary><div class="table-wrap"><table><thead><tr><th>題目</th><th>選擇</th><th>結果</th><th>時間</th></tr></thead><tbody>${s.events.map(e=>{const q=questions.find(q=>q.id===e.question_id);return `<tr><td>${q?.id} ${q?.title}</td><td>${q?.options[e.choice]?.label}</td><td>${e.correct?'✓ 答對':'再嘗試'}</td><td>${dateTime(e.created_at)}</td></tr>`;}).join('')||'<tr><td colspan="4">尚未作答</td></tr>'}</tbody></table></div></details>`).join('')}`}</section>`;$('#details').scrollIntoView({behavior:'smooth',block:'start'});
}
$('#home').onclick=()=>{if(!busy){home();focusMain();}};$('#curriculum').onclick=()=>$('#info').showModal();$('#teacher').onclick=()=>{if(busy)return;history.replaceState(null,'','#teacher');teacherToken?loadTeacher():teacherLogin();focusMain();};
if(location.hash==='#teacher')teacherToken?loadTeacher():teacherLogin();else{home();if(student){api('progress').then(r=>{events=r.events;persist();home();}).catch(err=>toast('暫未同步最新紀錄：'+err.message));}}
